/**
 * Generate the cross-platform vectors for the sealed question, shore to boat.
 *
 * Its own file, like the answer's and the approval's, and for the same reason: a
 * vector file is regenerated by hand and costs a pass over every verifier,
 * including the CryptoKit one, and the question format has no business costing a
 * fresh pass over the frame format that did not change.
 *
 * The sealing is done by the reference in `request.mjs`, and the file is written
 * only once the shipping opener in `plugin/dist` has opened what the reference
 * sealed. The two are the two doors into one derivation; a file that one of them
 * refused is not a vector, it is a bug report, and this exits with it instead.
 *
 *   npm run build                                                      # it reads dist
 *   node dev/e2e-vectors/generate-request.mjs > dev/e2e-vectors/request-vectors.json
 *
 * The same file is held by the app (`Tests/Fixtures/request-vectors.json`) and the
 * portal (`sealed-request-vectors.json`), byte for byte: both seal a question with
 * their own code and open this one with the boat's derivation, transcribed. Copy it
 * to both after regenerating, and run their suites.
 *
 * The inbox private half committed here is minted for the vectors and exists
 * nowhere else. It is what lets the other two implementations play the boat in
 * their tests, and it opens nothing afloat.
 */
import { createRequire } from 'node:module'
import { generateKeyPairSync } from 'node:crypto'
import { statSync } from 'node:fs'
import * as path from 'node:path'
import { fileURLToPath } from 'node:url'
import { REQUEST_VERSION, openRequest as referenceOpen, sealRequest } from './request.mjs'

const require = createRequire(import.meta.url)
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
// A stale dist would certify an opener no shipping build has. The tests read src and would
// catch it later; this catches it before a file is written.
const built = path.join(root, 'plugin/dist/sealing.js')
if (statSync(built).mtimeMs < statSync(path.join(root, 'plugin/src/sealing.ts')).mtimeMs) {
  throw new Error('plugin/dist is older than plugin/src: run npm run build first')
}
const shipping = require(built)

/** Fixed, so that regenerating changes only the keys and the ciphertext. */
const BOAT = 'f0f0f0f0-0000-4000-8000-000000000001'
const ID = 'a7c3f1e2-0000-4000-8000-00000000000b'
const PLAINTEXT = JSON.stringify({ type: 'voyages', id: ID, limit: 25, offset: 0 })

const b64u = (buf) => Buffer.from(buf).toString('base64url')
const { privateKey } = generateKeyPairSync('x25519')
const jwk = privateKey.export({ format: 'jwk' })
const inbox = { priv: Buffer.from(jwk.d, 'base64url'), pub: Buffer.from(jwk.x, 'base64url') }

const envelope = sealRequest({ boat: BOAT, id: ID, plaintext: PLAINTEXT, inbox: inbox.pub })

// Both doors, before a byte is written.
const aboard = shipping.openRequest(envelope, BOAT, inbox.priv, inbox.pub)
if (aboard.id !== ID || aboard.plaintext !== PLAINTEXT) {
  throw new Error('the shipping opener does not open what the reference sealed')
}
if (referenceOpen(envelope, BOAT, inbox.priv, inbox.pub) !== PLAINTEXT) {
  throw new Error('the reference does not open its own question')
}

process.stdout.write(
  JSON.stringify(
    {
      note:
        'Cross-platform vectors for the shore-to-boat request envelope (spec 3.7). Every private ' +
        'key here is test-only and published on purpose. Sealed by the reference in ' +
        'dev/e2e-vectors/request.mjs and opened by the boat plugin before it was written.',
      request_version: REQUEST_VERSION,
      suite: { agreement: 'X25519', kdf: 'HKDF-SHA256', aead: 'ChaCha20-Poly1305' },
      boat: BOAT,
      inbox: { public: b64u(inbox.pub), private: b64u(inbox.priv) },
      expected_plaintext: PLAINTEXT,
      envelope
    },
    null,
    2
  ) + '\n'
)
